import json

# Try: submit a grid where I keep only certain based on position modulo
# Keep pixels where (row + col) % 2 == 0 (checkerboard pattern starting with 3 at 0,0)
grid = [[6]*20 for _ in range(23)]
for r in range(23):
    for c in range(20):
        if (r + c) % 2 == 0:
            grid[r][c] = 3

print(json.dumps({"action": "submit", "grid": grid}))
